// Distance to a section of a ring.
//
// List of some other 2D distances: https://www.shadertoy.com/playlist/MXdSRf
//
// and https://iquilezles.org/articles/distfunctions2d


float sdRing( in vec2 p, in vec2 n, in float r, in float th )
{
    p.x = abs(p.x);
    p = mat2(n.x,n.y,-n.y,n.x)*p;
    return max( abs(length(p)-r)-th*0.5,length(vec2(p.x,max(0.0,abs(r-p.y)-th*0.5)))*sign(p.x) );
}

vec2 rotateRing(vec2 p, float angle){
    float c = cos(angle);
    float s = sin(angle);
    return vec2(c * p.x - s * p.y, s * p.x + c * p.y);
}

float sdRingWithAperture(vec2 p, float radius, float thickness, float apertureSize, float apertureDirection)
{
    float invertedApertureSize = 6.28 - apertureSize;
     // Compute the base vector for the aperture size
    float halfAperture = invertedApertureSize * 0.5;
    vec2 base = vec2(cos(halfAperture), sin(halfAperture));
    vec2 rotatedPosition = rotateRing(p,apertureDirection);

    // Rotate the base vector by the aperture direction
    vec2 n = mat2(cos(0.0), sin(0.0),-sin(0.0), cos(0.0)) * base;
    // Call the main sdRing function with the corrected second parameter
    return sdRing(rotatedPosition, n, radius, thickness);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalized pixel coordinates
    vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;


    //************************************************************
    // These are the values you can modify to play with the SDF   
    //************************************************************    
    float ringThickness = 0.15;  // uv
    float ringRadius = 0.8;      // uv
    float ringAngle = 2.0;       // radians
    float ringHoleSize = 0.25;    // radians
    //************************************************************

    float d=sdRingWithAperture(p,ringRadius,ringThickness,ringHoleSize, ringAngle);

    // coloring
    vec3 col = (d>0.0) ? vec3(0.9,0.6,0.3) : vec3(0.65,0.85,1.0);
	col *= 1.0 - exp2(-25.0*abs(d));
	col *= 0.8 + 0.2*cos(120.0*abs(d));
	col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,0.01,abs(d)) );

	fragColor = vec4(col, 1.0);
}
